     1→import { BattleResult, BattleEvent } from '../types/BattleTypes';
     2→import { submitBattleResult, type SubmitBattleResultResponse } from '../utils/battleLeaderboard';
     3→import { getBattleTier, getTierIndex } from '../utils/battleTier';
     4→import { BattleChannel } from '../utils/battleChannel';
     5→import BaseScene from './BaseScene';
     6→
     7→interface BattleResultData {
     8→  result: BattleResult;
     9→  roomCode: string;
    10→  userId?: string;
    11→  opponentId?: string;
    12→  isRanked?: boolean;
    13→}
    14→
    15→/**
    16→ * 대전 결과 씬
    17→ * - 승리/패배/연결끊김 표시
    18→ * - RP 변동 + 티어 표시
    19→ * - 재도전: 양쪽 모두 요청 시 BattleMatchScene 자동 복귀
    20→ * - 상대 재도전 의사 / 이탈 실시간 알림
    21→ */
    22→export default class BattleResultScene extends BaseScene {
    23→  private result: BattleResult = BattleResult.WIN;
    24→  private roomCode: string = '';
    25→  private userId: string = '';
    26→  private opponentId: string = '';
    27→  private isRanked: boolean = false;
    28→  private resultSubmitted: boolean = false;
    29→
    30→  // RP UI
    31→  private tierText?: Phaser.GameObjects.Text;
    32→  private rpDeltaText?: Phaser.GameObjects.Text;
    33→  private currentRpText?: Phaser.GameObjects.Text;
    34→
    35→  // 재도전 채널
    36→  private rematchChannel: BattleChannel | null = null;
    37→  private myRematchRequested: boolean = false;
    38→  private opponentRematchRequested: boolean = false;
    39→  private rematchTransitioning: boolean = false;
    40→  private opponentLeftHandled: boolean = false;
    41→
    42→  // 재도전 UI
    43→  private rematchBtn!: Phaser.GameObjects.Rectangle;
    44→  private rematchBtnLabel!: Phaser.GameObjects.Text;
    45→  private rematchStatusText!: Phaser.GameObjects.Text;
    46→
    47→  constructor() {
    48→    super('BattleResultScene');
    49→  }
    50→
    51→  init(data: BattleResultData) {
    52→    this.result = data.result ?? BattleResult.WIN;
    53→    this.roomCode = data.roomCode ?? '';
    54→    this.userId = data.userId ?? '';
    55→    this.opponentId = data.opponentId ?? '';
    56→    this.isRanked = data.isRanked ?? false;
    57→    this.resultSubmitted = false;
    58→    this.myRematchRequested = false;
    59→    this.opponentRematchRequested = false;
    60→    this.rematchTransitioning = false;
    61→    this.opponentLeftHandled = false;
    62→  }
    63→
    64→  preload() {
    65→    if (!this.textures.exists('background2')) {
    66→      this.load.image('background2', 'assets/backgrounds/background2.webp');
    67→    }
    68→  }
    69→
    70→  create() {
    71→    super.create();
    72→
    73→    // 배경
    74→    const bg = this.add.image(200, 300, 'background2');
    75→    bg.setDisplaySize(400, 600);
    76→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.75);
    77→
    78→    // 결과 텍스트
    79→    const isWin = this.result === BattleResult.WIN || this.result === BattleResult.DISCONNECT;
    80→    const resultText = this.result === BattleResult.WIN ? '🏆 승리! 🏆'
    81→      : this.result === BattleResult.DISCONNECT ? '🏆 부전승 🏆'
    82→      : '💀 패배... 💀';
    83→    const titleColor = isWin ? '#FFD700' : '#ff4444';
    84→
    85→    this.add.text(200, 85, resultText, {
    86→      fontSize: '36px',
    87→      color: titleColor,
    88→      fontStyle: 'bold',
    89→      stroke: '#000',
    90→      strokeThickness: 6,
    91→    }).setOrigin(0.5);
    92→
    93→    // 티어/RP 영역
    94→    if (this.isRanked) {
    95→      // 랭크전: 전적 제출 후 채워짐
    96→      this.tierText = this.add.text(200, 130, '전적 기록 중...', {
    97→        fontSize: '15px',
    98→        color: '#aaaaaa',
    99→        stroke: '#000',
   100→        strokeThickness: 3,
   101→      }).setOrigin(0.5);
   102→
   103→      this.rpDeltaText = this.add.text(200, 155, '', {
   104→        fontSize: '18px',
   105→        fontStyle: 'bold',
   106→        stroke: '#000',
   107→        strokeThickness: 4,
   108→      }).setOrigin(0.5);
   109→
   110→      this.currentRpText = this.add.text(200, 183, '', {
   111→        fontSize: '13px',
   112→        color: '#888888',
   113→        stroke: '#000',
   114→        strokeThickness: 3,
   115→      }).setOrigin(0.5);
   116→    } else {
   117→      // 친선전: RP 변동 없음 표시
   118→      this.add.text(200, 148, '친선전 — RP 변동 없음', {
   119→        fontSize: '14px',
   120→        color: '#666666',
   121→        stroke: '#000',
   122→        strokeThickness: 3,
   123→      }).setOrigin(0.5);
   124→    }
   125→
   126→    if (this.isRanked) {
   127→      // 랭크전: 재대전 없음 → 새 매칭 버튼
   128→      const newMatchBtn = this.add.rectangle(200, 310, 250, 50, 0x7a5c00);
   129→      newMatchBtn.setStrokeStyle(3, 0xFFD700);
   130→      this.add.text(200, 310, '🎖️ 새 랭크 매칭', {
   131→        fontSize: '20px',
   132→        color: '#FFD700',
   133→        fontStyle: 'bold',
   134→      }).setOrigin(0.5);
   135→      newMatchBtn.setInteractive({ useHandCursor: true });
   136→      newMatchBtn.on('pointerover', () => newMatchBtn.setAlpha(0.8));
   137→      newMatchBtn.on('pointerout', () => newMatchBtn.setAlpha(1));
   138→      newMatchBtn.on('pointerdown', () => {
   139→        if (this.rematchChannel) {
   140→          this.rematchChannel.destroyImmediate();
   141→          this.rematchChannel = null;
   142→        }
   143→        this.scene.start('BattleMatchScene');
   144→      });
   145→    } else {
   146→      // 친선전: 기존 재대전 버튼 유지
   147→      this.rematchStatusText = this.add.text(200, 250, '', {
   148→        fontSize: '14px',
   149→        color: '#FFD700',
   150→        fontStyle: 'bold',
   151→        stroke: '#000',
   152→        strokeThickness: 3,
   153→        align: 'center',
   154→      }).setOrigin(0.5);
   155→
   156→      this.rematchBtn = this.add.rectangle(200, 310, 250, 50, 0xe74c3c);
   157→      this.rematchBtn.setStrokeStyle(3, 0xffffff);
   158→      this.rematchBtnLabel = this.add.text(200, 310, '⚔️ 재대전', {
   159→        fontSize: '20px',
   160→        color: '#ffffff',
   161→        fontStyle: 'bold',
   162→      }).setOrigin(0.5);
   163→      this.rematchBtn.setInteractive({ useHandCursor: true });
   164→      this.rematchBtn.on('pointerover', () => {
   165→        if (!this.myRematchRequested) this.rematchBtn.setAlpha(0.8);
   166→      });
   167→      this.rematchBtn.on('pointerout', () => this.rematchBtn.setAlpha(1));
   168→      this.rematchBtn.on('pointerdown', () => this.handleRematchClick());
   169→    }
   170→
   171→    // 전적 보기 버튼
   172→    const rankBtn = this.add.rectangle(200, 380, 250, 50, 0x27ae60);
   173→    rankBtn.setStrokeStyle(3, 0xffffff);
   174→    this.add.text(200, 380, '🏆 전적 보기', {
   175→      fontSize: '20px',
   176→      color: '#ffffff',
   177→      fontStyle: 'bold',
   178→    }).setOrigin(0.5);
   179→    rankBtn.setInteractive({ useHandCursor: true });
   180→    rankBtn.on('pointerover', () => rankBtn.setAlpha(0.8));
   181→    rankBtn.on('pointerout', () => rankBtn.setAlpha(1));
   182→    rankBtn.on('pointerdown', () => this.navigateAway('BattleLeaderboardScene'));
   183→
   184→    // 메인 메뉴 텍스트 링크
   185→    const menuLink = this.add.text(200, 450, '메인 메뉴', {
   186→      fontSize: '16px',
   187→      color: '#aaaaaa',
   188→      stroke: '#000',
   189→      strokeThickness: 3,
   190→    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
   191→    menuLink.on('pointerover', () => menuLink.setColor('#ffffff'));
   192→    menuLink.on('pointerout', () => menuLink.setColor('#aaaaaa'));
   193→    menuLink.on('pointerdown', () => this.navigateAway('ModeSelectScene'));
   194→
   195→    // 전적 제출 (랭크전 + 친선전 모두)
   196→    if (!this.resultSubmitted) {
   197→      this.resultSubmitted = true;
   198→      submitBattleResult(this.result, this.opponentId, this.isRanked)
   199→        .then((res) => { if (this.isRanked) this.showRpResult(res); })
   200→        .catch((err) => {
   201→          console.warn('Battle result submit failed:', err);
   202→          if (this.tierText?.active) this.tierText.setText('전적 기록 실패');
   203→        });
   204→    }
   205→
   206→    // 재도전 채널 연결 (친선전만 — 랭크전은 재대전 없음)
   207→    if (this.roomCode && !this.isRanked) {
   208→      this.initRematchChannel();
   209→    }
   210→  }
   211→
   212→  /** 제출 응답 수신 후 RP/티어 UI 업데이트 */
   213→  private showRpResult(res: SubmitBattleResultResponse) {
   214→    if (!this.tierText?.active || !this.rpDeltaText?.active) return;
   215→
   216→    const oldTierIdx = getTierIndex(res.previousRp);
   217→    const newTierIdx = getTierIndex(res.ratingPoints);
   218→    const newTier = getBattleTier(res.ratingPoints);
   219→
   220→    if (newTierIdx > oldTierIdx) {
   221→      const oldTier = getBattleTier(res.previousRp);
   222→      this.tierText.setText(`${oldTier.icon} ${oldTier.name}  →  ${newTier.icon} ${newTier.name}`);
   223→      this.tierText.setColor('#FFD700');
   224→    } else {
   225→      this.tierText.setText(`${newTier.icon} ${newTier.name}  |  ${res.ratingPoints} RP`);
   226→      this.tierText.setColor('#cccccc');
   227→    }
   228→
   229→    const deltaStr = res.pointDelta >= 0 ? `+${res.pointDelta} RP` : `${res.pointDelta} RP`;
   230→    this.rpDeltaText.setText(deltaStr);
   231→    this.rpDeltaText.setColor(res.pointDelta >= 0 ? '#00ff88' : '#ff4444');
   232→
   233→    if (this.currentRpText?.active) {
   234→      this.currentRpText.setText(`현재 ${res.ratingPoints} RP`);
   235→    }
   236→  }
   237→
   238→  // ─── 재도전 채널 ────────────────────────────────────────────────
   239→
   240→  private async initRematchChannel() {
   241→    this.rematchChannel = new BattleChannel();
   242→    this.rematchChannel.joinResult(this.roomCode, this.userId);
   243→
   244→    // subscribe 전에 리스너 등록
   245→    this.rematchChannel.onEvent(BattleEvent.REMATCH_REQUEST, () => {
   246→      this.onOpponentRematchRequest();
   247→    });
   248→
   249→    // RESULT_LEAVE: 상대가 의도적으로 내비게이션 시 즉시 알림 (Broadcast 기반)
   250→    this.rematchChannel.onEvent(BattleEvent.RESULT_LEAVE, () => {
   251→      this.onOpponentLeft();
   252→    });
   253→
   254→    // Presence leave: 브라우저 종료 등 예기치 않은 이탈 fallback
   255→    this.rematchChannel.onPresenceLeave(() => {
   256→      this.onOpponentLeft();
   257→    });
   258→
   259→    await this.rematchChannel.subscribe();
   260→  }
   261→
   262→  /** 재대전 버튼 클릭 */
   263→  private handleRematchClick() {
   264→    if (this.myRematchRequested || this.rematchTransitioning) return;
   265→    this.myRematchRequested = true;
   266→
   267→    // 버튼 → 대기 상태
   268→    this.rematchBtn.setFillStyle(0x555555);
   269→    this.rematchBtn.removeInteractive();
   270→    this.rematchBtnLabel.setText('⏳ 상대 대기 중...');
   271→
   272→    // 상대에게 재도전 의사 전송
   273→    if (this.rematchChannel) {
   274→      this.rematchChannel.sendRematchRequest();
   275→    }
   276→
   277→    // 상대도 이미 요청해놨으면 바로 전환
   278→    this.checkBothRematch();
   279→  }
   280→
   281→  /** 상대가 재도전 요청을 보냈을 때 */
   282→  private onOpponentRematchRequest() {
   283→    if (this.rematchTransitioning) return;
   284→    this.opponentRematchRequested = true;
   285→
   286→    // 내가 아직 안 눌렀다면 → 강조 알림
   287→    if (!this.myRematchRequested) {
   288→      if (this.rematchStatusText?.active) {
   289→        this.rematchStatusText.setText('⚔️ 상대가 재도전을 원합니다!');
   290→        this.rematchStatusText.setColor('#FFD700');
   291→      }
   292→      // 버튼 펄스 애니메이션
   293→      this.tweens.add({
   294→        targets: this.rematchBtn,
   295→        scaleX: 1.06,
   296→        scaleY: 1.06,
   297→        duration: 280,
   298→        yoyo: true,
   299→        repeat: -1,
   300→      });
   301→    }
   302→
   303→    this.checkBothRematch();
   304→  }
   305→
   306→  /** 상대가 채널에서 이탈했을 때 (RESULT_LEAVE broadcast + Presence leave 양쪽에서 호출될 수 있음) */
   307→  private onOpponentLeft() {
   308→    if (this.rematchTransitioning || this.opponentRematchRequested || this.opponentLeftHandled) return;
   309→    this.opponentLeftHandled = true;
   310→
   311→    if (this.rematchStatusText?.active) {
   312→      this.rematchStatusText.setText('😢 상대가 나갔습니다');
   313→      this.rematchStatusText.setColor('#ff6666');
   314→    }
   315→
