    39→
    40→    // 타이틀
    41→    this.add.text(200, 40, '⚔️ 배틀 전적', {
    42→      fontSize: '28px',
    43→      color: '#ff4444',
    44→      fontStyle: 'bold',
    45→      stroke: '#000',
