    const modeLabelColor = this.isRanked ? '#FFD700' : '#aaaaaa';
    this.ui(this.add.text(200, 155, modeLabel, {
      fontSize: '14px', color: modeLabelColor,
      stroke: '#000', strokeThickness: 3,
