private clearUI() {
  this.removeInput();
  for (const obj of this.uiGroup) {
    if (obj.active) obj.destroy();
  }
  this.uiGroup = [];
  // TimerEvent는 GameObject가 아니므로 별도 정리
  for (const timer of this.uiTimers) {
    timer.remove();
  }
  this.uiTimers = [];
}

/** UI 요소를 그룹에 추가 (나중에 일괄 파괴용) */
private ui<T extends Phaser.GameObjects.GameObject>(obj: T): T {
  this.uiGroup.push(obj);
  return obj;
}

// ─── 상태 1: 메뉴 (방 만들기 / 방 참가 선택) ─────────────────────

private showMenu() {
  this.clearUI();

  // ── 정보 카드 (캐릭터 좌측 | 랭크 우측) ──────────────────────
  const def = getCharacterDef(getSafeSelectedCharacter());
  const stars = def.grade === 'UR' ? '★★★'
    : def.grade === 'SR' ? '★★'
    : def.grade === 'R'  ? '★'
    : def.grade;

  this.ui(this.add.rectangle(200, 170, 374, 130, 0x0d1b2a, 0.9)
    .setStrokeStyle(1, 0x334466));

  // 구분선
  const divGfx = this.add.graphics();
  divGfx.lineStyle(1, 0x334466, 0.8);
  divGfx.lineBetween(203, 108, 203, 232);
  this.ui(divGfx);

  // 캐릭터 이미지
  if (this.textures.exists(def.imageKey)) {
    this.ui(this.add.image(62, 170, def.imageKey).setDisplaySize(54, 76));
  }
  this.ui(this.add.text(95, 144, def.name, {
    fontSize: '15px', color: '#ffffff', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 3,
  }).setOrigin(0, 0.5));
  this.ui(this.add.text(95, 167, stars, {
    fontSize: '14px', color: def.gradeColor,
    stroke: '#000', strokeThickness: 2,
  }).setOrigin(0, 0.5));
  this.ui(this.add.text(95, 188, def.grade !== '등급외' ? def.grade : '등급외', {
    fontSize: '11px', color: '#888888',
    stroke: '#000', strokeThickness: 2,
  }).setOrigin(0, 0.5));

  // 랭크 뱃지 (우측)
  this.ui(this.add.text(295, 115, '내 랭크', {
    fontSize: '10px', color: '#666666', stroke: '#000', strokeThickness: 2,
  }).setOrigin(0.5));
  this.rankBadgeImg = this.ui(
    this.add.image(240, 167, 'rank_alpha').setDisplaySize(42, 42).setAlpha(0),
  );
  this.rankBadgeNameTxt = this.ui(this.add.text(270, 150, '---', {
    fontSize: '14px', color: '#666666', stroke: '#000', strokeThickness: 2,
  }).setOrigin(0, 0.5));
  this.rankBadgeRpTxt = this.ui(this.add.text(270, 169, '···', {
    fontSize: '13px', color: '#555555', stroke: '#000', strokeThickness: 2,
  }).setOrigin(0, 0.5));
  this.rankBadgeRankTxt = this.ui(this.add.text(270, 187, '', {
    fontSize: '12px', color: '#666666', stroke: '#000', strokeThickness: 2,
  }).setOrigin(0, 0.5));

  // 캐시된 데이터가 있으면 즉시 반영
  if (this.cachedMyRp !== null) {
    this.updateRankBadge(this.cachedMyRp, this.cachedMyRank);
  }

  // ── 캐릭터 선택 버튼 (매칭 버튼 스타일, 374×40) ─────────────
  // 카드 bottom=235, 여기서부터 버튼들이 고르게 분배됨
  const charBtn = this.ui(this.add.rectangle(200, 272, 374, 40, 0x1a3a5c));
  charBtn.setStrokeStyle(3, 0x4499dd);
  this.ui(this.add.text(200, 272, '👤 캐릭터 선택', {
    fontSize: '18px', color: '#aaddff', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 4,
  }).setOrigin(0.5));
  charBtn.setInteractive({ useHandCursor: true });
  charBtn.on('pointerover', () => charBtn.setFillStyle(0x254d70));
  charBtn.on('pointerout', () => charBtn.setFillStyle(0x1a3a5c));
  charBtn.on('pointerdown', () => {
    this.scene.start('CharacterSelectScene', { returnScene: 'BattleMatchScene' });
  });

  // ── 랭크 매칭 버튼 ───────────────────────────────────────────
  const rankedBtn = this.ui(this.add.rectangle(200, 358, 374, 60, 0x7a5c00));
  rankedBtn.setStrokeStyle(3, 0xFFD700);
  this.ui(this.add.text(200, 358, '🎖️ 랭크 매칭', {
    fontSize: '24px', color: '#FFD700', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 4,
  }).setOrigin(0.5));
  rankedBtn.setInteractive({ useHandCursor: true });
  rankedBtn.on('pointerover', () => rankedBtn.setFillStyle(0xa07a00));
  rankedBtn.on('pointerout', () => rankedBtn.setFillStyle(0x7a5c00));
  rankedBtn.on('pointerdown', () => this.startRankedMatchmaking());

  // ── 친선전 버튼 (좌우 나란히) ─────────────────────────────────
  this.ui(this.add.text(200, 422, '─── 친선전 (RP 없음) ───', {
    fontSize: '13px', color: '#888888',
    stroke: '#000', strokeThickness: 2,
  }).setOrigin(0.5));

  const createBtn = this.ui(this.add.rectangle(100, 458, 175, 48, 0xc0392b));
  createBtn.setStrokeStyle(2, 0xffffff);
  this.ui(this.add.text(100, 458, '🏠 방 만들기', {
    fontSize: '17px', color: '#ffffff', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 3,
  }).setOrigin(0.5));
  createBtn.setInteractive({ useHandCursor: true });
  createBtn.on('pointerover', () => createBtn.setFillStyle(0xe74c3c));
  createBtn.on('pointerout', () => createBtn.setFillStyle(0xc0392b));
  createBtn.on('pointerdown', () => this.handleCreateRoom());

  const joinBtn = this.ui(this.add.rectangle(300, 458, 175, 48, 0x2471a3));
  joinBtn.setStrokeStyle(2, 0xffffff);
  this.ui(this.add.text(300, 458, '🔗 방 참가', {
    fontSize: '17px', color: '#ffffff', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 3,
  }).setOrigin(0.5));
  joinBtn.setInteractive({ useHandCursor: true });
  joinBtn.on('pointerover', () => joinBtn.setFillStyle(0x3498db));
  joinBtn.on('pointerout', () => joinBtn.setFillStyle(0x2471a3));
  joinBtn.on('pointerdown', () => this.showJoinInput());

  // 전적 보기 + 메인 메뉴: 하단 밀착 배치
  const rankLink = this.ui(this.add.text(200, 537, '🏆 전적 보기', {
    fontSize: '16px', color: '#bbbbbb',
    stroke: '#000', strokeThickness: 3,
  }).setOrigin(0.5).setInteractive({ useHandCursor: true }));
  rankLink.on('pointerover', () => (rankLink as Phaser.GameObjects.Text).setColor('#FFD700'));
  rankLink.on('pointerout', () => (rankLink as Phaser.GameObjects.Text).setColor('#bbbbbb'));
  rankLink.on('pointerdown', () => this.scene.start('BattleLeaderboardScene'));
}

