  fontSize: '14px', color: '#bbbbbb', stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));
this.rankBadgeRankTxt = this.ui(this.add.text(284, 207, '', {
  fontSize: '13px', color: '#999999', stroke: '#000', strokeThickness: 2,
}).setOrigin(0, 0.5));

